def evaluate(results, relevant, k):
    recalls, rrs, per = [], [], []
    for res, rel in zip(results, relevant):
        hits = len([d for d in res if d in rel])
        recall = hits / len(rel)
        rr = 1 / (res.index(rel[0]) + 1) if rel[0] in res else 0.0
        recalls.append(recall); rrs.append(rr); per.append([round(recall, 4), round(rr, 4)])
    return {'recall_at_k': round(sum(recalls) / len(recalls), 4),
            'mrr_at_k': round(sum(rrs) / len(rrs), 4), 'per_query': per}

