def evaluate(results, relevant, k):
    if len(results) != len(relevant) or not results:
        raise ValueError('results and relevant must be non-empty and the same length')
    if k < 1:
        raise ValueError('k must be >= 1')
    per_query = []
    for res, rel_ids in zip(results, relevant):
        rel = set(rel_ids)
        if not rel:
            raise ValueError('every query needs at least one relevant id')
        top = res[:k]
        recall = len(rel & set(top)) / len(rel)
        rr = next((1 / rank for rank, d in enumerate(top, 1) if d in rel), 0.0)
        per_query.append((recall, rr))
    n = len(per_query)
    return {
        'recall_at_k': round(sum(r for r, _ in per_query) / n, 4),
        'mrr_at_k': round(sum(rr for _, rr in per_query) / n, 4),
        'per_query': [[round(r, 4), round(rr, 4)] for r, rr in per_query],
    }
